			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(){
			    
			    // 유효성 체크
			    if (!util.validate(app, "grpData")) return false;

			    var voDsSet = app.lookup("dsAprvPrcs");
			    var sStts   = app.lookup("cmbAprvSttsSwCd").value;
			    var sAprvCn = app.lookup("ipbAprvCn").value;
			    var sRjctCn = app.lookup("ipbRjctCsCn").value;
			    
			    if(sStts == "2" && sAprvCn == "") {
			        util.Msg.alert(app, "승인사유를 입력해주십시요.");
			        return false;
			    } else if(sStts == "3" && sRjctCn == "") {
			        util.Msg.alert(app, "반려사유를 입력해주십시요.");
			        return false;
			    }
			//    alert(voDsSet.getRowCount());
			    for(var i=0; i<voDsSet.getRowCount(); i++) {
			        voDsSet.setValue(i, "APRV_STTS_SE_CD", app.lookup("dmParam").getValue("APRV_STTS_SE_CD"));  //승인상태구분코드    
			        voDsSet.setValue(i, "AUTZR_NO"       , app.lookup("dmParam").getValue("AUTZR_NO"));         //승인자번호   
			        voDsSet.setValue(i, "APRV_DT"        , app.lookup("dmParam").getValue("APRV_DT"));          //승인일자    
			        voDsSet.setValue(i, "RJCT_CS_CN"     , app.lookup("dmParam").getValue("RJCT_CS_CN"));       //반려사유    
			        voDsSet.setValue(i, "APRV_CN"        , app.lookup("dmParam").getValue("APRV_CN"));          //승인내용    
			    }
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess){
			        
			        if(pbSuccess){
			            app.close();
			        } else {
			            util.Msg.alert(app, "승인(반려)처리 실패.");
			            return false;
			        }
			        
			    });
			    
			}

