			function onCmb1SelectionChange(/* cpr.events.CSelectionEvent */ e){
			    /** 
			     * @type cpr.controls.ComboBox
			     */
			    var vcCmb  = app.lookup("cmbAprvSttsSwCd");
			    var cbVal  = vcCmb.value;
			    
			    var vcGrpDefFormLot = app.lookup("grpDefForm").getLayout();
			    
			    // Row Visible 초기화
			    moPgmVisibleRowIdx.def.forEach(function(idx) {
			        vcGrpDefFormLot.setRowVisible(idx, false);
			    });
			    
			    // 서비스 유형에 따라 Row Visible 처리
			    moPgmVisibleRowIdx[cbVal].forEach(function(idx) {
			        vcGrpDefFormLot.setRowVisible(idx, true);
			    });
			    
			}

